    async def send_message(
        self,
        *,
        from_: str,
        to: typing.Sequence[str],
        channel: typing.Optional[SendMessageRequestChannel] = OMIT,
        text: typing.Optional[str] = OMIT,
        media_urls: typing.Optional[typing.Sequence[str]] = OMIT,
        title: typing.Optional[str] = OMIT,
        tag: typing.Optional[str] = OMIT,
        idempotency_key: typing.Optional[str] = OMIT,
        scheduled_at: typing.Optional[dt.datetime] = OMIT,
        failover_to_sms: typing.Optional[bool] = OMIT,
        rcs_suggestions: typing.Optional[typing.Sequence[RcsSuggestion]] = OMIT,
        dlt_entity_id: typing.Optional[str] = OMIT,
        dlt_header_id: typing.Optional[str] = OMIT,
        dlt_template_id: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncHttpResponse[Message]:
        """
        Sends an SMS, MMS or RCS message from one of your numbers or RCS senders to one or more recipients. Each number in `to` becomes its own message, with its own `id`, status and conversation, and the response body is the first recipient's message. Every recipient is checked against your opt-out list first, and a send with a future `scheduledAt` is stored with status `scheduled`.

        - `201` when every recipient was accepted, including an idempotent replay and a successful SMS fallback.
        - `202` when at least one recipient was recorded and at least one errored. Find the other recipients with `GET /messages` filtered by `tag` or `to`.
        - `422` when the recipient has opted out and nothing was recorded.
        - `502` when the send was rejected before a message was recorded. Retry with the same `idempotencyKey`.

        Track delivery with `GET /messages/{id}`, your webhooks (callbacks) or the WebSocket.

        Parameters
        ----------
        from_ : str
            The sender. For `sms` and `mms`, one of your Vobiz numbers in E.164 format, for example `+14155550100`. For `rcs`, the `senderName` of your RCS sender (from `GET /senders`); with `failoverToSms`, the SMS copy is sent from a number on your account.

        to : typing.Sequence[str]
            One or more recipient numbers in E.164 format. Each one becomes a separate message with its own `id`; blank entries and duplicates are ignored. At least one recipient is required.

        channel : typing.Optional[SendMessageRequestChannel]
            Channel to send on: `sms`, `mms` or `rcs`. Defaults to `sms`. An `sms` with `mediaUrls` to US or Canadian recipients is sent as MMS automatically.

        text : typing.Optional[str]
            Message body. Required for `sms` and `rcs`. A long SMS is split into segments and billed per segment (160 GSM-7 or 70 UCS-2 characters fit in one segment). For `mms`, provide `text`, `mediaUrls` or both, with `text` up to 5000 characters.

        media_urls : typing.Optional[typing.Sequence[str]]
            Publicly reachable `https` URLs of media to attach. MMS accepts up to 10. RCS sends the first URL as a file. An SMS to recipients outside the US and Canada is sent as text only.

        title : typing.Optional[str]
            Subject line of an MMS. Used only when the message is sent as MMS.

        tag : typing.Optional[str]
            Your own label, stored on every message the request creates. Filter `GET /messages` by it to find all recipients of one send or to group messages for reporting.

        idempotency_key : typing.Optional[str]
            A unique string you choose, for example a UUID or your own order ID, scoped to your account. Retrying with the same key returns the original message instead of sending again. With several recipients the key is applied per recipient.

        scheduled_at : typing.Optional[dt.datetime]
            Time to hold the message until, as an RFC 3339 / ISO 8601 timestamp such as `2026-11-01T09:00:00Z`. A future time stores the message with status `scheduled`; a past time or now sends immediately.

        failover_to_sms : typing.Optional[bool]
            Used only when `channel` is `rcs`. When `true` and the RCS send cannot go through, Vobiz sends the same `text` as SMS and the message's `channel` becomes `sms`. Defaults to `false`.

        rcs_suggestions : typing.Optional[typing.Sequence[RcsSuggestion]]
            Suggestion buttons (suggested replies and actions) to show under an RCS message. Used only when `channel` is `rcs`. See the RCS suggestion object for each `type`.

        dlt_entity_id : typing.Optional[str]
            India (TRAI DLT): the Principal Entity ID you registered on a TRAI DLT portal. Pass it on every message to Indian numbers.

        dlt_header_id : typing.Optional[str]
            India (TRAI DLT): the ID of the sender header you registered on a TRAI DLT portal. Pass it on every message to Indian numbers.

        dlt_template_id : typing.Optional[str]
            India (TRAI DLT): the ID of the content template you registered on a TRAI DLT portal. `text` must match that template with its variables filled in.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncHttpResponse[Message]
            Sent or scheduled for every recipient. Body is the first recipient's message.
        """
        _response = await self._client_wrapper.httpx_client.request(
            "api/v1/sms/messages",
            method="POST",
            json={
                "from": from_,
                "to": to,
                "channel": channel,
                "text": text,
                "mediaUrls": media_urls,
                "title": title,
                "tag": tag,
                "idempotencyKey": idempotency_key,
                "scheduledAt": scheduled_at,
                "failoverToSms": failover_to_sms,
                "rcsSuggestions": convert_and_respect_annotation_metadata(
                    object_=rcs_suggestions, annotation=typing.Sequence[RcsSuggestion], direction="write"
                ),
                "dltEntityId": dlt_entity_id,
                "dltHeaderId": dlt_header_id,
                "dltTemplateId": dlt_template_id,
            },
            headers={
                "content-type": "application/json",
            },
            request_options=request_options,
            omit=OMIT,
        )
        try:
            if 200 <= _response.status_code < 300:
                _data = typing.cast(
                    Message,
                    parse_obj_as(
                        type_=Message,  # type: ignore
                        object_=_response.json(),
                    ),
                )
                return AsyncHttpResponse(response=_response, data=_data)
            if _response.status_code == 400:
                raise BadRequestError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        typing.Any,
                        parse_obj_as(
                            type_=typing.Any,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 401:
                raise UnauthorizedError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        typing.Any,
                        parse_obj_as(
                            type_=typing.Any,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 422:
                raise UnprocessableEntityError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        typing.Any,
                        parse_obj_as(
                            type_=typing.Any,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 502:
                raise BadGatewayError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        typing.Any,
                        parse_obj_as(
                            type_=typing.Any,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            _response_json = _response.json()
        except JSONDecodeError:
            raise ApiError(status_code=_response.status_code, headers=dict(_response.headers), body=_response.text)
        except ValidationError as e:
            raise ParsingError(
                status_code=_response.status_code, headers=dict(_response.headers), body=_response.json(), cause=e
            )
        raise ApiError(status_code=_response.status_code, headers=dict(_response.headers), body=_response_json)

